import{_ as a,o as t,c as r,ae as o}from"./chunks/framework.CeK7r8F_.js";const u=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"usage-examples/index.md","filePath":"usage-examples/index.md"}'),l={name:"usage-examples/index.md"};function i(s,e,n,m,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><h2 id="a-virtual-filesystem" tabindex="-1">A virtual filesystem <a class="header-anchor" href="#a-virtual-filesystem" aria-label="Permalink to &quot;A virtual filesystem&quot;">​</a></h2><p><img src="https://dom-orm.erikpoehler.com/virtual-filesystem/assets/images/virtual-filesystem.png" alt="virtual filesystem"> This example is to illustrate how a filesystem tree can be persisted with DOM-ORM. See the <a href="https://github.com/vardumper/dom-orm/tree/main/demos/virtual-filesystem" target="_blank" rel="noreferrer">source code</a>.</p><p><a href="https://dom-orm.erikpoehler.com/virtual-filesystem/" target="_blank" rel="noreferrer">Virtual Filesystem Demo</a></p><h3 id="explanations" tabindex="-1">Explanations <a class="header-anchor" href="#explanations" aria-label="Permalink to &quot;Explanations&quot;">​</a></h3><ol><li>Look at the demo entities <a href="https://github.com/vardumper/dom-orm/blob/main/demos/virtual-filesystem/models/VirtualFolder.php" target="_blank" rel="noreferrer">VirtualFolder</a> and <a href="https://github.com/vardumper/dom-orm/blob/main/demos/virtual-filesystem/models/VirtualFile.php" target="_blank" rel="noreferrer">VirtualFile</a>. Both define what fields they consist of and how to store them in DOM-ORM by using PHP attributes.</li><li>In the Demo, you can rename files and folders and create new ones.</li><li>You wouldn&#39;t want to actually store file content in a XML file which is read to memory. This potentially crashes PHP or may consume too much memory. It&#39;s an example.</li><li>The Demo is reset automatically. It uses XSLT for rendering the XML directly.</li></ol><h2 id="a-minimal-blog" tabindex="-1">A minimal blog <a class="header-anchor" href="#a-minimal-blog" aria-label="Permalink to &quot;A minimal blog&quot;">​</a></h2><p><img src="https://dom-orm.erikpoehler.com/blog/assets/images/blog.png" alt="blog"></p><p><a href="https://dom-orm.erikpoehler.com/blog/" target="_blank" rel="noreferrer">Blog Demo</a></p><p>This example illustrates how to store Article, Image and Comment entities into a DOM-ORM XML flatfile database. See the <a href="https://github.com/vardumper/dom-orm/tree/main/demos/blog" target="_blank" rel="noreferrer">source code</a>.</p><h3 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h3><ol><li>In the Demo, you see a basic blog theme with Twig rendered templates.</li><li>Head to <a href="https://dom-orm.erikpoehler.com/blog/admin" target="_blank" rel="noreferrer">Admin</a> in order to add or delete posts and comments.</li><li>A note on images: in the demo we save base64 encoded binary data in the DOM ORM XML. When DOM ORM reads the XML it stores it into memory, so artificially bloating the XML is an anti-pattern. In production you would simply store a path to the file.</li><li>The Demo is reset automatically.</li></ol>',12)])])}const c=a(l,[["render",i]]);export{u as __pageData,c as default};
